 static final String SCHEMA="it_registration_"+UUID.randomUUID().toString().replace("-","");
 static final Path DIR=directory();
 static Path directory(){try{return Files.createTempDirectory("it_registration_");}catch(IOException e){throw new UncheckedIOException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.datasource.hikari.connection-init-sql",()->"SET search_path TO "+SCHEMA);p.add("rallye.crews.photo-directory",()->DIR.resolve("crews").toString());p.add("rallye.templates.image-directory",()->DIR.resolve("templates").toString());p.add("rallye.races.file-directory",()->DIR.resolve("events").toString());}
 @Autowired RegistrationService registrations;@Autowired CrewService crews;@Autowired EventService events;
 @Autowired TemplateService templates;@Autowired TemplateStore templateStore;@Autowired AccountStore accounts;
 @Autowired AccountCancellationService cancellation;@Autowired PreRaceAccountParticipationFacts facts;
 @Autowired JdbcTemplate jdbc;@Autowired MutableClock clock;@Autowired PlatformTransactionManager manager;@Autowired MockMvc mvc;
 @Autowired javax.sql.DataSource source;
 @Autowired cz.mh.rallye.rallye_backend.participation.persistence.CrewStartStore startStore;
 @MockitoSpyBean AuditStore audit;
 record Actor(UUID id,String token,AuthService.Principal principal){} Actor admin;
 TransactionTemplate tx(){return new TransactionTemplate(manager);}
 Actor actor(){return tx().execute(s->{UUID id=UUID.randomUUID();String email=id+"@example.test",token=new SecretTokens().create();Timestamp at=Timestamp.from(clock.instant());jdbc.update("INSERT INTO user_account(id,email,normalized_email,display_name,status,email_verified_at,created_at,updated_at) VALUES (?,?,?,'Captain','ACTIVE',?,?,?)",id,email,email,at,at,at);jdbc.update("INSERT INTO user_identity(id,account_id,provider,issuer,subject,password_hash,created_at) VALUES (?,?,'LOCAL','local',?,'synthetic-test-hash',?)",UUID.randomUUID(),id,id.toString(),at);UUID session=accounts.insertSession(id,new SecretTokens().hash(token),false,clock.instant(),clock.instant().plusSeconds(86400));return new Actor(id,token,new AuthService.Principal(id,session,false));});}
 @BeforeAll void bootstrap()throws IOException{admin=actor();String sql=AdministrationIT.bootstrapBody(admin.id());tx().executeWithoutResult(s->jdbc.execute(sql));}
 @AfterAll void cleanup()throws Exception{assertTrue(SCHEMA.matches("it_registration_[0-9a-f]{32}"));assertEquals("rallye_test",jdbc.queryForObject("SELECT current_database()",String.class));assertEquals("rallye_test",jdbc.queryForObject("SELECT current_user",String.class));jdbc.execute("DROP SCHEMA \""+SCHEMA+"\" CASCADE");try(var all=Files.walk(DIR)){for(Path p:all.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
 UUID event(){UUID template=UUID.randomUUID(),stage=UUID.randomUUID();tx().executeWithoutResult(s->{templates.list(admin.principal(),null,null,0,1);templateStore.insert(template,"Registration source",null,0,clock.instant());templateStore.insertStage(stage,template,1,"Station",1000L,10L);templateStore.instructionsMarkdown(stage,"Instructions");templateStore.configureStage(stage,new StageConfiguration(new StageConfiguration.Gps(false,null,null,null,null,null),new StageConfiguration.Code(true,"TEST",0L,false),new StageConfiguration.TimePenalty(false,null,null),new StageConfiguration.Delayed(false,null,null)));});templates.state(admin.principal(),template,0,"READY");return events.create(admin.principal(),template,1,UUID.randomUUID(),new EventService.Input("Registration event",null,null,clock.instant().plusSeconds(86400))).id();}
 UUID crew(Actor a){return crews.create(a.principal(),UUID.randomUUID(),"Crew "+UUID.randomUUID(),null,null,false,null).id();}
 RegistrationService.Created register(Actor a,UUID e,UUID c){return registrations.create(a.principal(),e,UUID.randomUUID(),c,"Jana\nPetr",1);}
 long count(String sql,Object... args){return jdbc.queryForObject(sql,Long.class,args);}
 String failure(Runnable action){return assertThrows(AuthFailure.class,action::run).code();}
 List<String> race(Callable<String> first,Callable<String> second)throws Exception{var gate=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await(10,TimeUnit.SECONDS);return first.call();});var b=pool.submit(()->{gate.await(10,TimeUnit.SECONDS);return second.call();});return List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
 String outcome(Runnable action){try{action.run();return "OK";}catch(AuthFailure f){return f.code();}}

