 @Test void candidateAndRegistrationPagingAreStableAndOwnerScoped(){var a=actor();var b=actor();UUID e=event();UUID c1=crew(a),c2=crew(a);register(a,e,c1);register(a,e,c2);register(b,e,crew(b));var all=registrations.list(a.principal(),e,"own",0,50);assertEquals(2,all.items().size());var p0=registrations.list(a.principal(),e,"own",0,1);var p1=registrations.list(a.principal(),e,"own",1,1);assertTrue(p0.hasMore());assertFalse(p1.hasMore());assertEquals(all.items().get(0).id(),p0.items().getFirst().id());assertEquals(all.items().get(1).id(),p1.items().getFirst().id());assertEquals(3,registrations.list(admin.principal(),e,"all",0,50).items().size());assertEquals("ADMIN_REQUIRED",failure(()->registrations.list(a.principal(),e,"all",0,50)));assertEquals(2,registrations.crews(a.principal(),e,0,50).items().size());assertTrue(registrations.crews(a.principal(),e,0,50).items().stream().allMatch(x->"ALREADY_REGISTERED".equals(x.blockedReason())));}
 @Test void compositionEditsRemainPossibleWhenClosedButNotAtEventEnd(){var a=actor();UUID e=event();var r=register(a,e,crew(a));registrations.settings(admin.principal(),e,0,null,null,"CLOSED");assertEquals(1,registrations.members(a.principal(),e,r.id(),0,"New\r\nNames",0).version());var saved=registrations.detail(a.principal(),e,r.id());assertEquals(saved,registrations.members(a.principal(),e,r.id(),1,"New\nNames",0));assertEquals("REGISTRATION_VERSION_CONFLICT",failure(()->registrations.members(a.principal(),e,r.id(),0,"Other",0)));jdbc.update("UPDATE race_event SET end_at=? WHERE id=?",Timestamp.from(clock.instant()),e);assertEquals("RACE_EVENT_ENDED",failure(()->registrations.members(a.principal(),e,r.id(),1,"Other",0)));assertEquals("EVENT_ENDED",registrations.detail(a.principal(),e,r.id()).editBlockedReason());}
 @Test void registrationProtectsCrewAndEventAndSurvivesAccountCancellation(){var a=actor();UUID e=event(),c=crew(a);var r=register(a,e,c);assertEquals("CREW_IN_USE",failure(()->crews.delete(a.principal(),c,0)));assertEquals("RACE_EVENT_IN_USE",failure(()->events.delete(admin.principal(),e,0)));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("DELETE FROM crew WHERE id=?",c));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("DELETE FROM race_event WHERE id=?",e));assertFalse(tx().execute(s->facts.forAccount(a.id())).historical());cancellation.administrator(admin.principal(),a.id(),UUID.randomUUID());assertEquals(0,count("SELECT count(*) FROM user_account WHERE id=?",a.id()));assertNull(jdbc.queryForObject("SELECT captain_account_id FROM crew WHERE id=?",UUID.class,c));assertEquals("Jana\nPetr",registrations.detail(admin.principal(),e,r.id()).membersText());}
 @Test void startedSnapshotIsImmutableAndMakesCaptainHistorical(){
  var a=actor();UUID e=event();var r=register(a,e,crew(a));
  var before=registrations.detail(a.principal(),e,r.id());assertEquals(0,before.version());assertFalse(before.compositionLocked());
  bindHistoricalFixture(a,e,r.id());
  var started=registrations.detail(a.principal(),e,r.id());assertEquals(before.version()+1,started.version());assertTrue(started.compositionLocked());assertFalse(started.canEditMembers());
  assertTrue(tx().execute(s->facts.forAccount(a.id())).historical());
  // Contract precedence is version -> event end -> individual start, even for a locked registration.
  assertEquals("REGISTRATION_VERSION_CONFLICT",failure(()->registrations.members(a.principal(),e,r.id(),before.version(),"Other",0)));
  assertEquals("REGISTRATION_COMPOSITION_LOCKED",failure(()->registrations.members(a.principal(),e,r.id(),started.version(),"Other",0)));
  assertEquals(started,registrations.detail(a.principal(),e,r.id()));
  assertEquals(0,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='REGISTRATION_MEMBERS_UPDATED'",r.id()));
  assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE crew_registration SET members_text='Other' WHERE id=?",r.id()));
  assertEquals(started,registrations.detail(a.principal(),e,r.id()));
  cancellation.administrator(admin.principal(),a.id(),UUID.randomUUID());
  assertEquals("ANONYMIZED",jdbc.queryForObject("SELECT status FROM user_account WHERE id=?",String.class,a.id()));
  assertEquals(a.id(),registrations.detail(admin.principal(),e,r.id()).historicalCaptainAccountId());
 }

